\set ON_ERROR_STOP on
-- ============================================================================
--  ESKİ HBYS BİLGİ ALANI (GEN3000 / "eski HBYS" MSSQL şeması) — eski.tanim
--
--  Eski HBYS'lerin tablo, kolon ve kod değerlerinin ANLAMI ve yeni sistemdeki karşılığı. Tek kaynak:
--  aktarım kuralları (esle.sql) buna göre yazılır; yeni bir eski HBYS kurulumu aktarılırken önce burası
--  okunur, kurulumun farklı kodları (ör. başka TAHSILAT.TUR değerleri) EKLENİR. Kayıtlar KOSUYOLU
--  (görüntüleme merkezi, 2026) incelemesinden çıkarıldı; "dogrulama" kolonu nasıl bilindiğini söyler:
--    olcum   = kaynak veride sayılarla doğrulandı (ör. toplam eşitliği)
--    kullanici = kullanıcının anlatımı
--    ad      = yalnız kolon adından çıkarım (doğrulanmadı)
--
--  Yeniden çalıştırılabilir: kendi kaynak_sistem satırlarını silip yeniden yazar.
-- ============================================================================
begin;

create schema if not exists eski;

create table if not exists eski.tanim (
    id            bigint generated by default as identity primary key,
    kaynak_sistem text not null,              -- 'GEN3000'
    tablo         text not null,              -- eski tablo (büyük harf, MSSQL adı)
    kolon         text not null default '',   -- '' = tablonun kendisi
    deger         text not null default '',   -- kod değeri ('' = kolonun genel anlamı)
    anlam         text not null,
    hedef         text not null default '',   -- yeni sistemdeki karşılık (tablo.kolon / kural)
    dogrulama     text not null default 'ad', -- olcum | kullanici | ad
    notlar        text not null default '',
    unique (kaynak_sistem, tablo, kolon, deger)
);
comment on table eski.tanim is 'Eski HBYS (GEN3000) tablo / kolon / kod anlamları ve yeni sistem karşılıkları - aktarim/eski-hbys/sozluk.sql';

delete from eski.tanim where kaynak_sistem = 'GEN3000';

